/**
 * Isaac Is Born
 * -------------
 * In old age Sarah bears Isaac — laughter — and the household feasts at his weaning. Stage: a shaded tent interior with woven hangings, a sleeping infant, Sarah's astonished joy; warm lamp light, the sound of celebration carried outside.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: tent
 * Game beat: Assemble a celebration tent.
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./abraham-kit.js.
 */

import { THREE, createScene, tent, person } from './abraham-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 3895796491, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x776542, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents */
    tent(W, group, -11.0, 0, -15.2, 1.01, 0xc8b088, W.r() * 6);
    tent(W, group, -1.9, 0, -18.3, 0.91, 0xc8b088, W.r() * 6);
    tent(W, group, 2.4, 0, -18.0, 0.97, 0xd8c8a0, W.r() * 6);
    tent(W, group, 16.3, 0, -10.8, 1.35, 0xc8b088, W.r() * 6);

    /* hero: the tent */
    tent(W, group, 0, 0, 0, 1.4, 0x9c8456, 0.2);
    W.disc([0, 5, -10], 5, 0xffef9c, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xd8b878, bend: 0.85, armR: [-0.2, 0.1], armL: [-0.2, -0.1], ry: 0.60, s: 1.19 });
    person(W, group, [4.5, 0, 6], { robe: 0x9c8456, bend: 0.85, armR: [-0.2, 0.1], armL: [-0.2, -0.1], ry: 0.54, s: 1.00 });
    person(W, group, [1, 0, -5], { robe: 0x776542, bend: 0.85, armR: [-0.2, 0.1], armL: [-0.2, -0.1], ry: 0.66, s: 1.13 });

    return W.finish();
}

export default { build };
